# Memoization (top-down)
from functools import lru_cache
@lru_cache
def fib(n):
    if n < 2: return n
    return fib(n-1) + fib(n-2)

# Tabulation (bottom-up)
def fib(n):
    if n < 2: return n
    table = [0, 1]
    for i in range(2, n + 1):
        table.append(table[i-1] + table[i-2])
    return table[n]

